   17	
   18	/**
   19	 * Answers one question about the account's own economy: is there a building or a technology it can
   20	 * legally queue now, and on which planet?
   21	 *
   22	 * Two things want a building. The chain wants the facility a later capability cannot exist without
   23	 * -- an account with no research lab can never research, and one with no shipyard can never own a
   24	 * ship -- and the economy wants the upgrade that repays itself fastest, or the storage that is about
   25	 * to overflow. The plan runs in two passes across the account's planets: first a warehouse that is
   26	 * about to overflow anywhere (it stops that planet producing, so it outranks every routine step on
   27	 * every other planet), then the routine economy planet by planet -- the energy a planet needs before
   28	 * it throttles, the chain's facilities, then the fastest-paying mine. The cross-planet storage pass
   29	 * is what keeps a full warehouse on one colony from waiting behind a routine mine on the homeworld.
   30	 *
   31	 * Both are only suggestions. Every gate is the host's own -- planet type, free queue space,
   32	 * requirements met against what is built *and* queued, and a price the planet can pay, which is the
   33	 * same set the building page shows a human -- so the module never restates an OGame rule. A target
   34	 * the host rejects is not an error but a fall-through: the planner tries the next one, which is what
   35	 * keeps a single impossible favourite from costing the account its whole build capability.
   36	 *
   37	 * Affordability is a real gate rather than a nicety: `BuildingQueueService::start()` cancels a queue
   38	 * item it cannot pay for, so publishing `build` while short of resources spends a queue slot and
   39	 * reports nothing at all.
   40	 */
   41	class QueueableBuildingPlanner
   42	{
   43	    /** The lab is one queue for the account, so its step has one slot beside the per-planet building steps. */
   44	    private const LAB_STEP = 'lab';
   45	
   46	    /** The pass that stands the facilities a bare planet's wall waits on: it is a fix, not a choice. */
   47	    private const WALL_STEP = 'wall';
   48	
   49	    public function __construct(
   50	        private PlayerServiceFactory $playerServiceFactory,
   51	        private FacilityChain $facilityChain,
   52	        private EnergyCapacity $energyCapacity,
   53	        private EconomyUpgrades $economyUpgrades,
   54	        private ReserveFloor $reserveFloor,
   55	        private BuildingQueueService $buildingQueueService,
   56	        private ResearchQueueService $researchQueueService,
   57	    ) {
   58	    }
   59	
   60	    public function plan(int $playerId, ?PlayerService $player = null): QueueableBuilding|QueueableResearch|null
   61	    {
   62	        return $this->steps($playerId, $player, 1)[0] ?? null;
   63	    }
   64	
   65	    /**
   66	     * Every queue a player would fill in one login: at most one building per planet, because each planet
   67	     * pays from its own stock and has its own build queue, and at most one technology, because the
   68	     * lab is one queue for the account. The order is plan()'s, so the first step is the one plan()
   69	     * returns.
   70	     *
   71	     * @return list<QueueableBuilding|QueueableResearch>
   72	     */
   73	    public function steps(int $playerId, ?PlayerService $player = null, int $limit = PHP_INT_MAX): array
   74	    {
   75	        // An account the module does not manage has no policy to apply, so it gets no capability.
   76	        $profile = AiProfile::query()->where('player_id', $playerId)->where('enabled', true)->first();
   77	        if ($profile === null) {
   78	            return [];
   79	        }
   80	
   81	        // The module owns profile rows; the host owns accounts. A profile can outlive its account or
   82	        // be written by a fixture, and loading an account the host does not have throws -- so the
   83	        // precondition is asked here rather than discovered in the host service.
   84	        if (!User::query()->whereKey($playerId)->exists()) {
   85	            return [];
   86	        }
   87	
   88	        // Refresh every planet's live balance once: the candidate pass reads stored amounts and
   89	        // energy, and a balance read stale is exactly the balance the queue later cancels on. The
   90	        // refresh stays in memory -- the observation path must not write.
   91	        $planets = ($player ?? $this->playerServiceFactory->make($playerId, true))->planets->all();
   92	        foreach ($planets as $planet) {
   93	            $planet->updateResources(false);
   94	            $planet->updateResourceProductionStats(false);
   95	            $planet->updateResourceStorageStats(false);
   96	        }
   97	
   98	        $passes = $this->passes($profile);
   99	
  100	        // What every planet is holding back, once per session: reading it walks the same candidate
  101	        // lists the passes do, so asking again inside each pass would repeat a planet's whole economy.
  102	        // It is also what keeps this list honest: the cohort reads "buildable" from exactly these
  103	        // steps, so a planet whose pile the goal reserves must not be offered here -- otherwise the
  104	        // read-out says buildable while the account rightly saves, and the invariant flags a saver
  105	        // for behaving as designed.
  106	        $goals = [];
  107	        foreach ($planets as $planet) {
  108	            $goals[$planet->getPlanetId()] = $this->savingsGoal($planet, $profile);
  109	        }
  110	
  111	        $steps = [];
  112	        foreach ($passes as $pass => $candidates) {
  113	            foreach ($planets as $planet) {
  114	                if (count($steps) >= $limit) {
  115	                    return array_values($steps);
  116	                }
  117	
  118	                $steps = $this->withStep($steps, $planet, $profile, $candidates, $goals[$planet->getPlanetId()], $pass === self::WALL_STEP);
  119	            }
  120	        }
  121	
  122	        return array_values($steps);
  123	    }
  124	
  125	    /**
  126	     * The candidate lists in the order the planner tries them. A warehouse about to overflow stops
  127	     * that planet producing, so its pass runs across every planet before any routine step; a full
  128	     * warehouse (E7) is a spend signal and comes next; then the routine economy: energy before it
  129	     * throttles, the chain's facilities, the fastest-paying mine. Public so a read-out explains a
  130	     * planet with the same lists the decision used.
  131	     *
  132	     * @return array<string, callable(PlanetService): list<BuildCandidate>>
  133	     */
  134	    public function passes(AiProfile $profile): array
  135	    {
  136	        return [
  137	            // A planet holding no defence while a sibling already stands a wall is past the
  138	            // account's opening with a sibling walled everywhere else: the facilities the wall
  139	            // itself waits on come before the economy, so the planet is not left naked behind a
  140	            // stock it is busy spending (QUAL-003). The step is the same shape as a wall order: a
  141	            // saving the economy is holding back does not veto it, because a planet with no wall is
  142	            // the state the account is fixing, not a step it chooses between (QUAL-003).
  143	            'wall' => fn (PlanetService $planet): array => $this->facilityChain->wallPending($planet),
  144	            'storage' => fn (PlanetService $planet): array => $this->economyUpgrades->storage($planet, $profile),
  145	            'surplus' => fn (PlanetService $planet): array => $this->economyUpgrades->spendSurplus($planet, $profile),
  146	            'routine' => fn (PlanetService $planet): array => [
  147	                ...$this->energyCapacity->pending($planet),
  148	                ...$this->facilityChain->pending($planet),
  149	                ...$this->economyUpgrades->storageForPrice($planet, $profile),
  150	                ...$this->economyUpgrades->production($planet, $profile),
  151	            ],
  152	        ];
  153	    }
  154	
  155	    /**
  156	     * The build queue and the lab run side by side, so a planet's building and the account's one
  157	     * technology are separate steps: a planet whose best candidate is a technology still builds.
  158	     *
  159	     * @param array<int|string, QueueableBuilding|QueueableResearch> $steps
  160	     * @param callable(PlanetService): list<BuildCandidate> $pass
  161	     * @return array<int|string, QueueableBuilding|QueueableResearch>
  162	     */
  163	    private function withStep(array $steps, PlanetService $planet, AiProfile $profile, callable $pass, ?SavingsGoal $goal, bool $wall = false): array
  164	    {
  165	        $candidates = $pass($planet);
  166	        $isResearch = static fn (BuildCandidate $candidate): bool => ObjectService::getObjectById($candidate->buildingId)->type === GameObjectType::Research;
  167	
  168	        // The candidate list is in priority order, so whichever queue its first entry belongs to is tried first.
  169	        $queues = [$planet->getPlanetId() => false, self::LAB_STEP => true];
  170	        if ($candidates !== [] && $isResearch($candidates[0])) {
  171	            $queues = array_reverse($queues, true);
  172	        }
  173	
  174	        foreach ($queues as $key => $research) {
  175	            if (isset($steps[$key])) {
  176	                continue;
  177	            }
  178	
  179	            $step = $this->firstQueueable($planet, $profile, array_values(array_filter($candidates, static fn (BuildCandidate $candidate): bool => $isResearch($candidate) === $research)), $wall ? null : $goal);
  180	            if ($step !== null) {
  181	                $steps[$key] = $step;
  182	            }
  183	        }
  184	
  185	        return $steps;
  186	    }
  187	
  188	    /**
  189	     * The first candidate this planet can actually queue, or null when none of them is legal.
  190	     *
  191	     * @param list<BuildCandidate> $candidates
  192	     */
  193	    private function firstQueueable(PlanetService $planet, AiProfile $profile, array $candidates, ?SavingsGoal $goal): QueueableBuilding|QueueableResearch|null
  194	    {
  195	        foreach ($candidates as $candidate) {
  196	            if (!$this->canSpendFor($planet, $goal, $candidate)) {
  197	                continue;
  198	            }
  199	
  200	            // Which queue takes a step is the host's object type, not this module's opinion: the
  201	            // chain hands over prerequisites, and a technology among them is research.
  202	            if (ObjectService::getObjectById($candidate->buildingId)->type === GameObjectType::Research) {
  203	                $research = $this->queueableResearch($planet, $candidate);
  204	                if ($research === null) {
  205	                    continue;
  206	                }
  207	
  208	                return $research;
  209	            }
  210	
  211	            $planetId = $planet->getPlanetId();
  212	            if (!$this->canQueue($planet, $candidate)) {
  213	                continue;
  214	            }
