    3	namespace Modules\AI\Domain\Decision;
    4	
    5	use OGame\Factories\GameMissionFactory;
    6	use OGame\GameObjects\Models\Abstracts\GameObject;
    7	use OGame\GameObjects\Models\Calculations\CalculationType;
    8	use OGame\GameObjects\Models\Enums\GameObjectType;
    9	use OGame\GameObjects\Models\UnitObject;
   10	use OGame\Models\Enums\PlanetType;
   11	use OGame\Services\ObjectService;
   12	use OGame\Services\PlanetService;
   13	use OGame\Services\PlayerService;
   14	
   15	/**
   16	 * The building this planet still needs before the next thing the account wants to produce is
   17	 * possible at all.
   18	 *
   19	 * A seeded account owns nothing, so without this the account grows resources forever and never owns
   20	 * a laboratory or a shipyard -- which is how six of its capabilities became permanently unreachable.
   21	 * The chain is what connects the account's ambitions to the buildings that gate them.
   22	 *
   23	 * Nothing here names an object. The ambitions are whatever the host offers as research or as a unit,
   24	 * and the requirements are the host's own recursive requirement graph, so a module or an expansion
   25	 * that adds a ship, a technology or a building is part of the plan the moment the host knows about
   26	 * it -- and a host that changes a prerequisite changes this plan with no edit here.
   27	 *
   28	 * The module's only policy is the order, and it is the level the host asks for: the easiest unlock
   29	 * first. A player picks up the small prerequisites as they go, and ordering by the requirement
   30	 * rather than by the building is what keeps the plan from rushing the largest shipyard in the game
   31	 * while the account still has no laboratory. Only the level the host asks for counts, because level
   32	 * one of a robotics factory never unlocks a shipyard and treating "something is built" as done would
   33	 * stall the chain one step below its goal.
   34	 *
   35	 * The account works on one ambition at a time: the cheapest thing it cannot yet produce. Satisfying
   36	 * the union of every ambition's prerequisites instead is a ladder with no top -- the catalogue always
   37	 * names one more deep unlock, so the chain never finishes, the economy never gets a turn, and the
   38	 * account ends the day with a level-seven shipyard standing over level-three mines. A player picks a
   39	 * goal, stands what it needs, and goes back to mining; the next goal gets its turn on a later
   40	 * session, and the economy ranks in between.
   41	 *
   42	 * A step the planet cannot pay for because it produces none of a resource the step costs is blocked
   43	 * the same way a missing level is, so the producer of that resource is a chain step too: a player
   44	 * mines what they are short of, and the synthesizer stands before the robotics factory exactly the
   45	 * way the laboratory does.
   46	 *
   47	 * A step is whatever queue accepts it: the host's catalogue holds buildings and technologies beside
   48	 * each other, and a technology gating a laboratory is as much a prerequisite as the laboratory
   49	 * itself. Which queue takes the step is the planner's question, answered from the host's object type.
   50	 */
   51	class FacilityChain
   52	{
   53	    /** The resources a planet mines; energy is absent because capacity has its own rule ahead of the chain. */
   54	    private const MINED_RESOURCES = ['metal', 'crystal', 'deuterium'];
   55	
   56	    /** The moon station the account wants; module taste, never a source of truth for its requirements. */
   57	    private const PHALANX_STATION = 'sensor_phalanx';
   58	
   59	    /** The second moon station, only useful as a pair; module taste, requirements host-read. */
   60	    private const JUMP_GATE_STATION = 'jump_gate';
   61	
   62	    /** @return list<BuildCandidate> the unmet prerequisites of the one ambition in hand, easiest unlock first */
   63	    public function pending(PlanetService $planet): array
   64	    {
   65	        $ordered = [];
   66	        $producers = [];
   67	
   68	        $ambition = $this->nextAmbition($planet);
   69	        if ($ambition !== null) {
   70	            foreach (ObjectService::getRecursiveRequirements($ambition->machine_name) as $machineName => $level) {
   71	                $this->addRequirement($planet, $machineName, $level, $ordered, $producers);
   72	            }
   73	        }
   74	
   75	        // Capability research (R2): a research a host mission waits on is a step in its own right,
   76	        // whether or not any unit needs it. The chain is the module's only research source, so
   77	        // without this a leaf technology that unlocks a mission -- astrophysics for colonise and
   78	        // expedition -- is never reached, and that mission's whole capability stays unreachable
   79	        // however long the account plays. The technology is never named here: it comes from the
   80	        // mission's own answer, so a mission a mod adds is climbed once the host knows it.
   81	        foreach ($this->missionRequiredResearch() as $machineName => $level) {
   82	            $this->addRequirement($planet, $machineName, $level, $ordered, $producers, 'capability');
   83	
   84	            foreach (ObjectService::getRecursiveRequirements($machineName) as $prerequisite => $prerequisiteLevel) {
   85	                $this->addRequirement($planet, $prerequisite, $prerequisiteLevel, $ordered, $producers);
   86	            }
   87	        }
   88	
   89	        // SP8: a slot-bound account — zero free fleet slots — reaches the technology that
   90	        // raises the ceiling, never named here (R11 publishes the object behind the value).
   91	        foreach ($this->fleetSlotCeilingResearch($planet) as $machineName => $level) {
   92	            $this->addRequirement($planet, $machineName, $level, $ordered, $producers, 'slot-ceiling');
   93	        }
   94	
   95	        // A planet-capped account — every colony slot it has unlocked is already settled —
   96	        // reaches the technology that raises the planet ceiling, never named here either. The
   97	        // mission's own answer only asks for the level that first makes colonising possible, so
   98	        // without this the account settles its one colony and stops with capacity to spare.
   99	        foreach ($this->planetCeilingResearch($planet) as $machineName => $level) {
  100	            $this->addRequirement($planet, $machineName, $level, $ordered, $producers, 'planet-ceiling');
  101	        }
  102	
  103	        // A moon the account owns wants its sensor phalanx: the station is module taste, and
  104	        // the host's own recursive requirement graph puts the lunar base first (RV-008).
  105	        if ($planet->getPlanetType() === PlanetType::Moon) {
  106	            $this->addRequirement($planet, self::PHALANX_STATION, 1, $ordered, $producers, 'moon-station');
  107	
  108	            foreach (ObjectService::getRecursiveRequirements(self::PHALANX_STATION) as $machineName => $level) {
  109	                $this->addRequirement($planet, $machineName, $level, $ordered, $producers, 'moon-station');
  110	            }
  111	
  112	            // A jump gate is only a save as a pair, so it is a chain step once the account owns
  113	            // two moons (RV-009).
  114	            if ($this->hasTwoMoons($planet)) {
  115	                $this->addRequirement($planet, self::JUMP_GATE_STATION, 1, $ordered, $producers, 'moon-station');
  116	
  117	                foreach (ObjectService::getRecursiveRequirements(self::JUMP_GATE_STATION) as $machineName => $level) {
  118	                    $this->addRequirement($planet, $machineName, $level, $ordered, $producers, 'moon-station');
  119	                }
  120	            }
  121	        }
  122	
  123	        // A planet that holds no defence at all while a sibling already stands a wall wants the
  124	        // facilities the host's own smallest defence unit needs: the yard cannot take a defence order
  125	        // before those stand, so the planet stays naked beside its walled sibling forever, and the
  126	        // wall keeps growing where it already is (measured live 2 Oct 2026: planets at zero defence
  127	        // beside a sibling holding 21,084 units). The unit is never named: it is the cheapest the
  128	        // host's defence registry offers, and its prerequisites are the host's recursive graph.
  129	        foreach ($this->wallPrerequisites($planet) as $machineName => $level) {
  130	            $this->addRequirement($planet, $machineName, $level, $ordered, $producers, 'wall-prerequisite');
  131	        }
  132	
  133	        // A prerequisite requested at several levels appears once per level, so the account climbs
  134	        // to the next one it is missing.
  135	        $this->sortOrdered($ordered, $planet);
  136	
  137	        return $this->withProducers($ordered, $producers, $planet);
  138	    }
  139	
  140	    /**
  141	     * The facilities the host's own smallest defence unit needs, for the planet the rule applies to,
  142	     * as a list of its own.
  143	     *
  144	     * `pending()` already carries them among the chain's steps, but a chain step is one candidate the
  145	     * economy ranks against the mines: a planet whose stock overflows is spending, and the surplus pass
  146	     * asked first, so the wall's prerequisites never got their turn and the planet stayed naked beside
  147	     * its walled sibling (measured live 2 Oct 2026: 7-8 planets at zero defence while one held the
  148	     * wall). The building planner gives this list its own pass ahead of the economy, and nothing is
  149	     * named here: the unit is the cheapest the host registers and the steps are the host's own graph.
  150	     *
  151	     * @return list<BuildCandidate>
  152	     */
  153	    public function wallPending(PlanetService $planet): array
  154	    {
  155	        // Own pass, ahead of the economy: the facilities the wall waits on are a fix, not a choice.
  156	        $ordered = [];
  157	        $producers = [];
  158	
  159	        foreach ($this->wallPrerequisites($planet) as $machineName => $level) {
  160	            $this->addRequirement($planet, $machineName, $level, $ordered, $producers, 'wall-prerequisite');
  161	        }
  162	
  163	        $this->sortOrdered($ordered, $planet);
  164	
  165	        return $this->withProducers($ordered, $producers, $planet);
  166	    }
  167	
  168	    /**
  169	     * The chain's stated order: unmet host prerequisites first, then facilities before research
  170	     * (an ordinary player stands the factory before chasing the technology or yard it enables), then
  171	     * by the level asked for and the price of the step.
  172	     *
  173	     * @param array<string, array{level: int, candidate: BuildCandidate}> $ordered
  174	     */
  175	    private function sortOrdered(array &$ordered, PlanetService $planet): void
  176	    {
  177	        usort($ordered, function (array $left, array $right) use ($planet): int {
  178	            $leftObject = ObjectService::getObjectById($left['candidate']->buildingId);
  179	            $rightObject = ObjectService::getObjectById($right['candidate']->buildingId);
  180	            $dependencies = $this->unmetDependencyCount($leftObject->machine_name, $planet)
  181	                <=> $this->unmetDependencyCount($rightObject->machine_name, $planet);
  182	            if ($dependencies !== 0) {
  183	                return $dependencies;
  184	            }
