  400	    /**
  401	     * @param array<string, GameObject> $producers
  402	     * @return list<BuildCandidate> cheapest first, the same convention as the capacity rule
  403	     */
  404	    private function producerSteps(array $producers, PlanetService $planet): array
  405	    {
  406	        $objects = array_values($producers);
  407	
  408	        usort($objects, static fn (GameObject $left, GameObject $right): int =>
  409	            ObjectService::getObjectPrice($left->machine_name, $planet)->sum()
  410	            <=> ObjectService::getObjectPrice($right->machine_name, $planet)->sum());
  411	
  412	        return array_map(static fn (GameObject $object): BuildCandidate => app()->makeWith(BuildCandidate::class, [
  413	            'buildingId' => $object->id,
  414	            'reason' => 'chain:' . $object->machine_name,
  415	        ]), $objects);
  416	    }
  417	
  418	    /**
  419	     * How far this account already is with one prerequisite.
  420	     *
  421	     * The host keeps a planet's levels on the planet and a technology's on the player, so asking the
  422	     * planet for a technology answers zero every time and would offer the same step forever.
  423	     */
  424	    private function currentLevel(PlanetService $planet, string $machineName): int
  425	    {
  426	        $isResearch = ObjectService::getObjectByMachineName($machineName)->type === GameObjectType::Research;
  427	
  428	        if (!$isResearch) {
  429	            return $planet->getObjectLevel($machineName);
  430	        }
  431	
  432	        // A planet always has an owner on the host; the nullable signature is the
  433	        // host's, so a missing player reads as level zero rather than crashing a
  434	        // decision on data the host itself would not normally be without.
  435	        return $planet->getPlayer()?->getResearchLevel($machineName) ?? 0;
  436	    }
  437	
  438	    /**
  439	     * The facilities the host's own smallest defence unit requires, or none when this planet does not
  440	     * need them.
  441	     *
  442	     * A planet needs them exactly when it holds no defence while a sibling of the same account
  443	     * already stands one: that is the account past its opening, with a wall it built everywhere it
  444	     * could reach, so the reasons the unit planner has for waiting no longer apply and the facility
  445	     * that gates the wall is as much a prerequisite as a laboratory gating a technology.
  446	     *
  447	     * @return array<string, int>
  448	     */
  449	    private function wallPrerequisites(PlanetService $planet): array
  450	    {
  451	        if (! $this->nakedBesideWalled($planet)) {
  452	            return [];
  453	        }
  454	
  455	        $unit = $this->smallestDefenceUnit();
  456	
  457	        return $unit === null ? [] : ObjectService::getRecursiveRequirements($unit->machine_name);
  458	    }
  459	
  460	    /**
  461	     * Whether this planet holds nothing while a sibling of the same account holds something.
  462	     *
  463	     * "Holds" is the unit planner's own answer -- built plus already paid for in the yard -- and not the
  464	     * built-only count: the account has left its opening the moment its first wall order is placed, so the
  465	     * sibling's bare neighbour is reached from that login rather than one login behind a wall that is
