public function wallPending(PlanetService $planet): array
{
    $ordered = [];
    $producers = [];
    foreach ($this->wallPrerequisites($planet) as $machineName => $level) {
        $this->addRequirement($planet, $machineName, $level, $ordered, $producers, 'wall-prerequisite');
