    3	namespace Modules\AI\Domain\Decision;
    4	
    5	use Modules\AI\Models\AiProfile;
    6	use OGame\Factories\PlayerServiceFactory;
    7	use OGame\GameMissions\TransportMission;
    8	use OGame\Models\Enums\PlanetType;
    9	use OGame\Models\FleetMission;
   10	use OGame\Models\Resources;
   11	use OGame\Models\User;
   12	use OGame\Services\ObjectService;
   13	use OGame\Services\PlanetService;
   14	use OGame\Services\PlayerService;
   15	
   16	/**
   17	 * Whether this account should ferry resources from one of its bodies to another, and which.
   18	 *
   19	 * A colony that cannot pay for its next level waits on the homeworld's surplus; a player looks at
   20	 * what the colony wants to build next, subtracts what is already on it and already flying to it, and
   21	 * ships the difference from the planet that can spare it without starving itself (E4/X1). The
   22	 * shortfall is netted against in-flight transports so one hole is never funded twice, the source must
   23	 * keep its reserve (SP5), and a shipment below the ordinary minimum is not worth the fleet's time.
   24	 *
   25	 * Nothing here names a game object. What a planet wants next is the same host-quoted step the
   26	 * economy planner asks -- storage overflow, energy, the facility chain, then the best mine -- and its
   27	 * price is the host's price, so an extension that adds a build or a resource changes the ferry with
   28	 * no module edit.
   29	 */
   30	class QueueableTransferPlanner
   31	{
   32	    /**
   33	     * r4fek's documented floor: combined metal and crystal below this is not worth a shipment.
   34	     * Shared with the dispatch adapter, which re-applies it to the clamped amount rather than
   35	     * flying a fleet for what is left of a spent surplus.
   36	     */
   37	    public const MINIMUM_SHIPMENT = 50_000;
   38	
   39	    /** A planet at this fraction of its storage is about to overflow and is swept (E9). */
   40	    private const SURPLUS_RATIO = 0.8;
   41	
   42	    public function __construct(
   43	        private PlayerServiceFactory $playerServiceFactory,
   44	        private EconomyUpgrades $economyUpgrades,
   45	        private EnergyCapacity $energyCapacity,
   46	        private FacilityChain $facilityChain,
   47	        private ReserveFloor $reserveFloor,
   48	    ) {
   49	    }
   50	
   51	    public function plan(int $playerId): ?QueueableTransfer
   52	    {
   53	        $profile = AiProfile::query()->where('player_id', $playerId)->where('enabled', true)->first();
   54	        if ($profile === null) {
   55	            return null;
   56	        }
   57	
   58	        if (!User::query()->whereKey($playerId)->exists()) {
   59	            return null;
   60	        }
   61	
   62	        $player = $this->playerServiceFactory->make($playerId, true);
   63	        $planets = $player->planets->all();
   64	        if (count($planets) < 2) {
   65	            return null;
   66	        }
   67	
   68	        foreach ($planets as $planet) {
   69	            $planet->updateResources(false);
   70	            $planet->updateResourceProductionStats(false);
   71	            $planet->updateResourceStorageStats(false);
   72	        }
   73	
   74	        foreach ($planets as $target) {
   75	            $need = $this->need($target, $profile, $playerId);
   76	            if ($need === null || !$this->worthShipping($need)) {
   77	                continue;
   78	            }
   79	
   80	            $source = $this->source($planets, $target, $need, $player);
   81	            if ($source === null) {
   82	                continue;
   83	            }
   84	
   85	            return app()->makeWith(QueueableTransfer::class, [
   86	                'sourcePlanetId' => $source->getPlanetId(),
   87	                'targetPlanetId' => $target->getPlanetId(),
   88	                'metal' => (int) round($need->metal->get()),
   89	                'crystal' => (int) round($need->crystal->get()),
   90	                'deuterium' => (int) round($need->deuterium->get()),
   91	            ]);
   92	        }
   93	
   94	        return $this->surplus($planets, $player);
   95	    }
   96	
   97	    /**
   98	     * The reverse of the need-driven ferry: a planet about to overflow ships its
   99	     * above-floor surplus to the best-developed body, so the mines do not stall
  100	     * (E9/X2). A moon keeps its deuterium for fleet jumps; a planet sweeps all
  101	     * three resources.
  102	     *
  103	     * @param array<PlanetService> $planets
  104	     */
  105	    private function surplus(array $planets, PlayerService $player): ?QueueableTransfer
  106	    {
  107	        $drop = $this->dropBody($planets);
  108	        if ($drop === null) {
  109	            return null;
  110	        }
  111	
  112	        foreach ($planets as $source) {
  113	            if ($source->getPlanetId() === $drop->getPlanetId() || !$this->nearCap($source)) {
  114	                continue;
  115	            }
  116	
  117	            $floor = $this->reserveFloor->floor($source, ReserveFloor::ECONOMY_HOURS);
  118	            $shipment = $this->aboveFloor($source, $floor, $source->getPlanetType() === PlanetType::Moon);
  119	            if (!$this->worthShipping($shipment) || !$this->hasCargo($source, $player)) {
  120	                continue;
  121	            }
  122	
  123	            return app()->makeWith(QueueableTransfer::class, [
  124	                'sourcePlanetId' => $source->getPlanetId(),
  125	                'targetPlanetId' => $drop->getPlanetId(),
  126	                'metal' => (int) round($shipment->metal->get()),
  127	                'crystal' => (int) round($shipment->crystal->get()),
  128	                'deuterium' => (int) round($shipment->deuterium->get()),
  129	            ]);
  130	        }
  131	
  132	        return null;
  133	    }
  134	
  135	    /**
  136	     * The most developed own planet, by the host's building count: the drop the
  137	     * surplus consolidates onto. Moons are never the drop.
  138	     *
  139	     * @param array<PlanetService> $planets
  140	     */
  141	    private function dropBody(array $planets): ?PlanetService
  142	    {
  143	        $best = null;
  144	        foreach ($planets as $planet) {
  145	            if ($planet->getPlanetType() === PlanetType::Moon) {
  146	                continue;
  147	            }
  148	
  149	            if ($best === null || $planet->getBuildingCount() > $best->getBuildingCount()) {
  150	                $best = $planet;
  151	            }
  152	        }
  153	
  154	        return $best;
  155	    }
  156	
  157	    /** Whether either stored resource is at or past the near-cap threshold. */
  158	    private function nearCap(PlanetService $planet): bool
  159	    {
  160	        return $planet->metal()->get() >= self::SURPLUS_RATIO * $planet->metalStorage()->get()
  161	            || $planet->crystal()->get() >= self::SURPLUS_RATIO * $planet->crystalStorage()->get();
  162	    }
  163	
  164	    /** What a body ships above its reserve floor; a moon keeps its deuterium. */
  165	    private function aboveFloor(PlanetService $source, Resources $floor, bool $keepDeuterium): Resources
  166	    {
  167	        return new Resources(
  168	            max(0.0, $source->metal()->get() - $floor->metal->get()),
  169	            max(0.0, $source->crystal()->get() - $floor->crystal->get()),
  170	            $keepDeuterium ? 0.0 : max(0.0, $source->deuterium()->get() - $floor->deuterium->get()),
  171	        );
  172	    }
  173	
  174	    /**
  175	     * What this planet is short for its next level: its price minus what is already there and already
  176	     * flying to it, floored at zero so a planet that has enough ships nothing.
  177	     */
  178	    private function need(PlanetService $target, AiProfile $profile, int $playerId): ?Resources
  179	    {
  180	        $price = $this->nextStepPrice($target, $profile);
  181	        if ($price === null) {
  182	            return null;
  183	        }
  184	
  185	        $inFlight = $this->inFlightTo($target, $playerId);
  186	
  187	        return new Resources(
  188	            max(0.0, $price->metal->get() - $target->metal()->get() - $inFlight->metal->get()),
  189	            max(0.0, $price->crystal->get() - $target->crystal()->get() - $inFlight->crystal->get()),
  190	            max(0.0, $price->deuterium->get() - $target->deuterium()->get() - $inFlight->deuterium->get()),
  191	        );
  192	    }
  193	
  194	    /**
  195	     * The next level this planet wants, in the same order the economy planner takes: storage that is
  196	     * about to overflow, energy before the throttle, the chain's facilities, then the best mine.
  197	     */
  198	    private function nextStepPrice(PlanetService $planet, AiProfile $profile): ?Resources
  199	    {
  200	        $candidates = [
